INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=21284&keyref=6007684', '3A2163', now(), 'Official source captured 2026-09-11. THB 6,087,000; 192.5 sq.wah; single-storey residential row building 197/7 with ten rooms and carport. Part of deed 48651 used as neighbouring access, approx 20.5 sq.wah included in total. Nineteen source images; building photos dated 2025-06-16. Navigation/map agree. All-status duplicate search by code/page/deeds/address/nearby coordinates found no matches.') ;
